local isArray = require(script.Parent:WaitForChild("isArray"))
require(script.Parent.Parent.Parent.Parent.Parent:WaitForChild(".luau-aliases"):WaitForChild("@jsdotlua"):WaitForChild("es7-types"))

local function concat(list, ...)
	local v = 0
	local clone, v2

	if isArray(list) then
		clone = table.clone(list)
		v2 = #list
	else
		v2 = v + 1
		clone = {
			[v2] = list
		}
	end

	for i = 1, select("#", ...) do
		local v3 = select(i, ...)
		local typeName = typeof(v3)

		if v3 == nil then
			continue
		end

		if typeName == "table" then
			for i2 = 1, #v3 do
				v2 += 1
				clone[v2] = v3[i2]
			end
		else
			v2 += 1
			clone[v2] = v3
		end
	end

	return clone
end

return concat